# cc-probe.sh — lets a real Claude Code create a session in a private
# configuration directory (t/cc-compat/probe), then checks that csm reads
# it: the directory name of a long path with non-ASCII characters and an
# emoji, the project path, the version, and githubRepoPaths.
#
# Usage: tools/cc-compat/cc-probe.sh [CLAUDE_EXECUTABLE]
#   default: claude from PATH
#
# Without a login "claude -p" stops with "Not logged in", but only after
# it has written the session file; the prompt never reaches the API.
# Nothing outside t/cc-compat/probe is written by the probe.
#
# Exit status: 0 all checks passed, 1 some failed, 2 Claude Code missing.

ROOT=$(cd "$(dirname "$0")/../.." && pwd -P)
PROBE=$ROOT/t/cc-compat/probe
CLAUDE=${1:-claude}
CSM=$ROOT/csm
FAILED=0
CHECKS=0

check()
{
	CHECKS=$((CHECKS + 1))
	if [ "$1" -eq 0 ]
	then
		echo "ok   $2"
	else
		echo "FAIL $2"
		FAILED=$((FAILED + 1))
	fi
}

if ! command -v "$CLAUDE" >/dev/null 2>&1
then
	echo "cc-probe: no Claude Code executable \"$CLAUDE\"" >&2
	exit 2
fi
if [ ! -x "$CSM" ]
then
	echo "cc-probe: csm is not built; run make first" >&2
	exit 2
fi

case $PROBE
in
*/t/cc-compat/probe)
	rm -rf "$PROBE"
	;;
esac
CONFIG=$PROBE/config
# Long enough for a hashed directory name, with a space, a dot, Polish
# letters and an emoji (two UTF-16 units).
WORK="$PROBE/work/głęboki katalog ę ą 🙂 z.kropką"
WORK="$WORK/bardzo długa nazwa katalogu próbnego numer jeden"
WORK="$WORK/bardzo długa nazwa katalogu próbnego numer dwa"
WORK="$WORK/bardzo długa nazwa katalogu próbnego numer trzy"
mkdir -p "$CONFIG" "$WORK" || exit 1

# A GitHub remote makes Claude Code record the repository root in
# githubRepoPaths (when it gets that far without a login).
(
	cd "$WORK" &&
	git init -q --template= &&
	git remote add origin https://github.com/csm-probe/Probe-Repo.git
) || exit 1

VERSION=$("$CLAUDE" --version 2>/dev/null | sed -n '1s/^\([0-9][0-9.]*\).*/\1/p')
echo "Claude Code $VERSION ($CLAUDE), probe in $PROBE"

# Claude Code may wait for input; perl's alarm bounds the run.
(
	cd "$WORK" &&
	CLAUDE_CONFIG_DIR=$CONFIG perl -e 'alarm shift; exec @ARGV or die "exec: $!\n"' 120 \
	    "$CLAUDE" -p "csm compatibility probe" </dev/null >"$PROBE/claude.out" 2>&1
)
echo "claude -p exit status $?: $(head -c 200 "$PROBE/claude.out" | tr '\n' ' ')"

COUNT=$(ls "$CONFIG/projects" 2>/dev/null | wc -l | tr -d ' ')
[ "$COUNT" -eq 1 ]
check $? "one session directory created ($COUNT)"
DIR=$(ls "$CONFIG/projects" 2>/dev/null | head -1)
LEN=$(printf '%s' "$DIR" | wc -c | tr -d ' ')
[ "$LEN" -gt 200 ]
check $? "directory name is a long, hashed one ($LEN bytes)"

# The survey checks the name against an encoder written apart from csm.
perl "$ROOT/tools/cc-compat/cc-data.pl" -c "$CONFIG" -g "$CONFIG/.claude.json" \
    "$VERSION" "$VERSION" >"$PROBE/data.txt" 2>&1
grep -q 'long names verified  *1$' "$PROBE/data.txt"
check $? "first cwd encodes to the directory name (independent encoder)"
sed -n '/^Problems:/,/^$/p' "$PROBE/data.txt" | grep -v '^Problems:' | sed 's/^/     /'

CLAUDE_CONFIG_DIR=$CONFIG "$CSM" -l --json >"$PROBE/csm-l.json" 2>"$PROBE/csm-l.err"
check $? "csm -l --json runs"
perl -MJSON::PP -e '
	local $/;
	utf8::decode($ARGV[0]);
	my $l = decode_json(<STDIN>);
	exit 1 unless @$l == 1;
	exit 1 unless $l->[0]{path} eq $ARGV[0] && $l->[0]{state} eq "active" && $l->[0]{sessions} == 1;
' "$WORK" <"$PROBE/csm-l.json"
check $? "csm -l: one active directory with the logical project path and one session"

CLAUDE_CONFIG_DIR=$CONFIG "$CSM" -s "$WORK" >"$PROBE/csm-s.txt" 2>&1
check $? "csm -s finds the project"

perl -MJSON::PP -e '
	local $/;
	utf8::decode($ARGV[0]);
	my $g = decode_json(<STDIN>);
	exit 2 unless exists $g->{githubRepoPaths};
	my $a = $g->{githubRepoPaths}{"csm-probe/probe-repo"} or exit 1;
	exit(($a->[0] // "") eq $ARGV[0] ? 0 : 1);
' "$(cd "$WORK" && pwd -P)" <"$CONFIG/.claude.json" 2>/dev/null
case $?
in
0)
	check 0 "githubRepoPaths: lower-case key, real path first"
	;;
2)
	echo "--   githubRepoPaths not written (Claude Code stops before it without a login)"
	;;
*)
	check 1 "githubRepoPaths: lower-case key, real path first"
	;;
esac

grep -o '"version":"[^"]*"' "$CONFIG/projects/$DIR"/*.jsonl 2>/dev/null | tail -1 | grep -q "\"$VERSION\""
check $? "session lines carry \"version\":\"$VERSION\""

echo "cc-probe: $CHECKS checks, $FAILED failed"
[ "$FAILED" -eq 0 ]
